const std = @import("std");
fn path(b: *std.Build, name: []const u8) std.Build.LazyPath { return .{ .cwd_relative = b.pathFromRoot(name) }; }
pub fn build(b: *std.Build) void {
    const target=b.standardTargetOptions(.{}); const optimize=b.standardOptimizeOption(.{}); const neutral=b.option(bool,"backend-neutral","Register FFI::Native C/Zig/Odin selector") orelse false;
    const odin=b.option([]const u8,"odin-object","Pinned Odin native object") orelse "../competition/odin-out/competitive.o"; const odin_query=b.option([]const u8,"odin-query-object","Pinned Odin query object") orelse "../sqlite/odin-out/query.o";
    const extension=b.addLibrary(.{.name="zig_suite",.linkage=.dynamic,.root_module=b.createModule(.{.root_source_file=path(b,"../src/root.zig"),.target=target,.optimize=optimize,.link_libc=true})}); for([_][]const u8{"../src","../sqlite","../conformance"})|inc|extension.root_module.addIncludePath(path(b,inc));
    const query=b.addLibrary(.{.name="zig_suite_query",.linkage=.static,.root_module=b.createModule(.{.root_source_file=path(b,"../sqlite/query.zig"),.target=target,.optimize=optimize,.link_libc=true})}); query.root_module.addIncludePath(path(b,"../sqlite"));
    const native_flags=&.{"-std=c11","-Wall","-Wextra","-Werror","-UNDEBUG","-ffp-contract=off"};
    if(neutral){extension.root_module.addObjectFile(path(b,odin));for([_][]const u8{"../src/backends.c","../src/competitive.c","../conformance/conformance.c"})|s|extension.root_module.addCSourceFile(.{.file=path(b,s),.flags=native_flags});}
    if(b.option([]const u8,"mruby-root","Built test VM, not DragonRuby SDK"))|mruby|{
        const boxing=b.option(enum{word,nan,none},"boxing","Matching VM boxing") orelse .word; const published=b.option(bool,"published","Published DragonRuby mruby patch") orelse false;
        const base=[_][]const u8{"-std=c11","-Wall","-Wextra","-Werror","-UNDEBUG","-DDRBZ_SUITE_TEST_HOST","-DDRBZ_SQLITE_QUERY","-DMRB_NO_PRESYM",if(published)"-DDRBZ_PUBLISHED_MRUBY" else "-DDRBZ_UPSTREAM_MRUBY",switch(boxing){.word=>"-DMRB_WORD_BOXING",.nan=>"-DMRB_NAN_BOXING",.none=>"-DMRB_NO_BOXING"},if(boxing==.nan)"-DMRB_INT32" else "-DMRB_INT64"};
        const renamed=base++[_][]const u8{"-Ddrb_register_c_extensions=drbz_register_legacy_extensions"}; const legacy:[]const []const u8=if(neutral)&renamed else &base;
        extension.root_module.addIncludePath(b.path("support"));extension.root_module.addSystemIncludePath(.{.cwd_relative=b.pathJoin(&.{mruby,"include"})});extension.root_module.addCSourceFile(.{.file=b.path("bridge.c"),.flags=legacy});
