    }else if(b.option([]const u8,"sdk-include","Matching proprietary dragonruby.h/mruby headers"))|sdk|{
        const sqlite=b.option(bool,"sqlite-query","Enable cached query_json") orelse false;extension.root_module.addSystemIncludePath(.{.cwd_relative=sdk});const base=[_][]const u8{"-std=c11","-Wall","-Wextra"};const q=base++[_][]const u8{"-DDRBZ_SQLITE_QUERY"};const normal:[]const []const u8=if(sqlite)&q else &base;const rn=q++[_][]const u8{"-Ddrb_register_c_extensions=drbz_register_legacy_extensions"};const r0=base++[_][]const u8{"-Ddrb_register_c_extensions=drbz_register_legacy_extensions"};const legacy:[]const []const u8=if(!neutral)normal else if(sqlite)&rn else &r0;extension.root_module.addCSourceFile(.{.file=b.path("bridge.c"),.flags=legacy});if(neutral){extension.root_module.addCSourceFile(.{.file=b.path("backend.c"),.flags=normal});if(sqlite){extension.root_module.addCSourceFile(.{.file=path(b,"../sqlite/query_c.c"),.flags=normal});extension.root_module.addObjectFile(path(b,odin_query));}}if(sqlite){extension.root_module.linkLibrary(query);extension.root_module.linkSystemLibrary("sqlite3",.{});}if(target.result.os.tag==.macos)extension.linker_allow_shlib_undefined=true;b.installArtifact(extension);
    }else{const fail=b.addFail("Provide -Dmruby-root=/test-vm or -Dsdk-include=/matching/sdk/include");b.default_step.dependOn(&fail.step);}
